    const cards=document.querySelectorAll('#dashboard>.kpis .kpi');
    cards[0].querySelector('.kpi-label').textContent='Target '+range.label;
    cards[0].querySelector('strong').textContent=rupiah(target);
    cards[0].querySelector('small').textContent=items.length+' target aktif';
    cards[1].querySelector('.kpi-label').textContent='Realisasi '+range.label;
    cards[1].querySelector('strong').textContent=rupiah(actual);
    cards[1].querySelector('small').textContent=moneyPercent+'% dari target penghimpunan';
    cards[2].querySelector('.kpi-label').textContent='Capaian '+range.label;
    cards[2].querySelector('strong').textContent=percent+'%';
    cards[2].querySelector('small').textContent='Rata-rata '+items.length+' target';
