  function resetUserForm(){editingUserId=null;byId('userForm').reset();byId('newUserDivision').disabled=false;byId('newUserPassword').required=true;byId('newUserPassword').placeholder='Minimal 8 karakter';byId('userForm').querySelector('.form-actions .primary').textContent='Buat akun';byId('userFormCard').classList.remove('open')}
  byId('addUser').onclick=()=>{resetUserForm();byId('userFormCard').classList.add('open')};
  window.editUser=id=>{const user=currentUsers.find(item=>item.id===id);if(!user)return;editingUserId=id;byId('newUserName').value=user.name;byId('newUserEmail').value=user.email;byId('newUserDivision').value=user.division_name||user.division;byId('newUserDivision').disabled=false;byId('newUserPassword').value='';byId('newUserPassword').required=false;byId('newUserPassword').placeholder='Kosongkan jika tidak diganti';byId('userForm').querySelector('.form-actions .primary').textContent='Simpan perubahan';byId('userFormCard').classList.add('open');byId('userFormCard').scrollIntoView({behavior:'smooth'})};
  window.deleteUser=async id=>{const user=currentUsers.find(item=>item.id===id);if(!user||!confirm(`Ajukan penghapusan akun ${user.name} kepada Ketua?`))return;try{const result=await api('/api/users?id='+id,{method:'DELETE',body:'{}'});await loadDeletionRequests();toast(result.message)}catch(error){toast(error.message)}};
  byId('cancelUser').onclick=resetUserForm;
  byId('userForm').onsubmit=async event=>{event.preventDefault();try{const payload={id:editingUserId,name:byId('newUserName').value,email:byId('newUserEmail').value,division:byId('newUserDivision').value,password:byId('newUserPassword').value},editing=Boolean(editingUserId),result=await api('/api/users',{method:editing?'PUT':'POST',body:JSON.stringify(payload)});resetUserForm();await loadUsers();if(result.pending_approval)await loadPolicyApprovals();toast(result.message||(editing?'Akun dan kata sandi berhasil diperbarui.':'Akun divisi berhasil dibuat dan terintegrasi.'))}catch(error){toast(error.message)}};
  byId('manageRole').onclick=()=>toast('Perubahan peran utama hanya dapat dilakukan oleh Ketua.');
  const budgetMobileButton=document.createElement('button');budgetMobileButton.dataset.page='anggaran';budgetMobileButton.innerHTML='<b>Rp</b>Anggaran';budgetMobileButton.onclick=()=>navigate('anggaran');byId('mobileNav').appendChild(budgetMobileButton);
  const cashOutCard=document.createElement('article');cashOutCard.className='card kpi';cashOutCard.innerHTML='<span class="kpi-label">Arus Kas Keluar</span><strong id="cashOutTotal">Rp 0</strong><small>Termasuk uang muka internal</small>';document.querySelector('#keuangan .finance-kpis').appendChild(cashOutCard);
  const budgetStatuses={submitted:'Menunggu Bendahara',treasurer_approved:'Menunggu Ketua',chair_approved:'Siap dicairkan',disbursed:'Dana dicairkan',accountability:'Proses LPJ',completed:'LPJ selesai',rejected:'Ditolak'};
  function budgetActions(item){const treasurer=currentUser?.division==='Bendahara',chair=currentUser?.role==='ketua',owner=currentUser?.division===item.division;let html='';if(treasurer&&item.status==='submitted')html='<button class="primary" data-budget-action="treasurer_approve">Verifikasi</button><button class="secondary" data-budget-action="reject">Tolak</button>';if(chair&&item.status==='treasurer_approved')html='<button class="primary" data-budget-action="chair_approve">Setujui</button><button class="secondary" data-budget-action="reject">Tolak</button>';if(treasurer&&item.status==='chair_approved')html='<button class="primary" data-budget-action="disburse">Catat pencairan</button>';if(owner&&['disbursed','accountability'].includes(item.status))html+=`<form class="budget-usage-form" data-budget-use><input type="date" name="date" value="${today()}" required><input name="category" placeholder="Kategori belanja" required><input type="number" min="1" max="${item.remaining_amount}" name="amount" placeholder="Nominal" required><input name="description" placeholder="Rincian penggunaan" required><input name="proof_note" placeholder="Nomor/keterangan bukti"><button class="primary">Tambah penggunaan</button></form>`;return html}
  function bindBudgetActions(){byId('budgetList').querySelectorAll('[data-budget-action]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-budget-id]'),action=button.dataset.budgetAction,note=action==='reject'?(prompt('Alasan penolakan:')||''):'';if(action==='reject'&&!note)return;try{const result=await api('/api/budget-requests',{method:'PUT',body:JSON.stringify({id:Number(card.dataset.budgetId),action,note})});await Promise.all([loadBudgetRequests(),loadFinances()]);toast(result.message)}catch(error){toast(error.message)}});byId('budgetList').querySelectorAll('[data-budget-use]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),id=Number(form.closest('[data-budget-id]').dataset.budgetId);try{const result=await api('/api/budget-requests',{method:'PUT',body:JSON.stringify({id,action:'add_usage',date:values.date,category:values.category,amount:Number(values.amount),description:values.description,proof_note:values.proof_note})});await Promise.all([loadBudgetRequests(),loadFinances()]);toast(result.message)}catch(error){toast(error.message)}})}
  async function loadBudgetRequests(){try{const data=await api('/api/budget-requests'),requested=data.items.reduce((sum,item)=>sum+item.amount,0),disbursed=data.items.reduce((sum,item)=>sum+item.disbursed_amount,0),used=data.items.reduce((sum,item)=>sum+item.used_amount,0);byId('budgetSummary').innerHTML=`<article class="card kpi"><span class="kpi-label">Total diajukan</span><strong>${rupiah(requested)}</strong></article><article class="card kpi"><span class="kpi-label">Sudah dicairkan</span><strong>${rupiah(disbursed)}</strong></article><article class="card kpi"><span class="kpi-label">Sudah digunakan</span><strong>${rupiah(used)}</strong></article><article class="card kpi"><span class="kpi-label">Belum dipertanggungjawabkan</span><strong>${rupiah(disbursed-used)}</strong></article>`;byId('budgetList').innerHTML=data.items.length?data.items.map(item=>`<article class="card budget-card" data-budget-id="${item.id}"><div class="budget-card-head"><div><span class="budget-code">${escapeHtml(item.request_code)}</span><h4>${escapeHtml(item.division)} · ${rupiah(item.amount)}</h4><p>${escapeHtml(item.purpose)}</p></div><span class="pill ${item.status==='completed'?'green':item.status==='rejected'?'red':'yellow'}">${budgetStatuses[item.status]||item.status}</span></div><div class="budget-flow"><span class="${item.treasurer_at?'done':''}">Bendahara</span><span class="${item.chair_at?'done':''}">Ketua</span><span class="${item.disbursed_at?'done':''}">Dicairkan</span><span class="${item.status==='completed'?'done':''}">LPJ</span></div>${item.disbursed_amount?`<div class="budget-amounts"><span>Dicairkan <b>${rupiah(item.disbursed_amount)}</b></span><span>Penggunaan <b>${rupiah(item.used_amount)}</b></span><span>Sisa <b>${rupiah(item.remaining_amount)}</b></span></div>`:''}${item.usages.length?`<div class="budget-usages">${item.usages.map(use=>`<div><span>${escapeHtml(use.usage_date)} · ${escapeHtml(use.category)}</span><b>${rupiah(use.amount)}</b><small>${escapeHtml(use.description)}${use.proof_note?' · Bukti: '+escapeHtml(use.proof_note):''}</small></div>`).join('')}</div>`:''}<div class="budget-actions">${budgetActions(item)}</div></article>`).join(''):'<article class="card empty-row">Belum ada pengajuan anggaran.</article>';bindBudgetActions()}catch(error){toast(error.message)}}
  byId('budgetRequestForm').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/budget-requests',{method:'POST',body:JSON.stringify({division:byId('budgetDivision').value,amount:Number(byId('budgetAmount').value),purpose:byId('budgetPurpose').value})});event.target.reset();applyUser(currentUser);await loadBudgetRequests();toast(result.message)}catch(error){toast(error.message)}};
  const loadFinancesAccountingBase=loadFinances;loadFinances=async()=>{await loadFinancesAccountingBase();try{const data=await api('/api/transactions?'+rangeQuery());byId('cashOutTotal').textContent=rupiah(data.summary.cash_out);if(['ketua','sekretaris'].includes(currentUser?.role)||['Bendahara','Administrasi'].includes(currentUser?.division)){const units=[...new Set([...unitNames,...data.items.map(item=>item.division)])],totals=Object.fromEntries(units.map(unit=>[unit,{income:0,expense:0}]));data.items.forEach(item=>{if(!totals[item.division])return;if(item.transaction_type==='pemasukan')totals[item.division].income+=item.amount;else if(item.accounting_type!=='internal_advance')totals[item.division].expense+=item.amount});byId('treasuryRows').innerHTML=units.map(unit=>`<tr><td><b>${unit}</b></td><td>${rupiah(totals[unit].income)}</td><td>${rupiah(totals[unit].expense)}</td><td><b>${rupiah(totals[unit].income-totals[unit].expense)}</b></td></tr>`).join('')}}catch(error){toast(error.message)}};
  document.getElementById('date').valueAsDate=new Date();
  const ctx=document.getElementById('trendChart');if(window.Chart)new Chart(ctx,{type:'bar',data:{labels:['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep'],datasets:[{label:'Target',data:[80,90,95,100,110,120,125,135,145],backgroundColor:'#dfe7e3',borderRadius:7,barThickness:18},{label:'Realisasi',data:[60,72,81,86,95,103,106,118,132],type:'line',borderColor:'#177a5b',backgroundColor:'#177a5b',tension:.4,pointRadius:4,pointBorderWidth:2,pointBackgroundColor:'#fff',pointBorderColor:'#177a5b'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,grid:{color:'#eef1ef'},border:{display:false},ticks:{font:{size:10},callback:v=>'Rp '+v+' jt'}}}}});
  const loadWorkspaceBase=loadWorkspace;loadWorkspace=()=>{loadWorkspaceBase();loadBudgetRequests();if(['ketua','sekretaris'].includes(currentUser?.role))loadPolicyApprovals()};
  checkSession();
